update public.questions set subject = 'History', topic = 'Medieval', type = 'mcq', difficulty = 'medium', body = 'The Dadu Panth, a sect of nirguna bhakti whose founder''s verses were collected as the ''Dadu Vani'', took root mainly in:', body_hi = 'दादू पंथ, निर्गुण भक्ति का एक संप्रदाय जिसके संस्थापक के पद ''दादू वाणी'' में संकलित हुए, मुख्यतः कहाँ जड़ें जमा सका?', explanation = 'Dadu Dayal (1544-1603), a cotton-carder by tradition, spent most of his life in Rajasthan -- at Sambhar, Amber and finally Naraina near Jaipur, which remains the seat of the Dadu Panth; like Kabir, whom he revered, he rejected idol worship, caste distinctions and ritual, and taught devotion to a formless God in the language of the people. His disciples Rajjab and Sundardas carried the teaching further and compiled his verses; the sect later also kept a body of armed ''naga'' ascetics who served Rajput rulers. Bengal''s great bhakti movement was the Vaishnavism of Chaitanya, Maharashtra''s the Varkari tradition, and Punjab''s the teaching of Guru Nanak.', explanation_hi = 'दादू दयाल (1544-1603), परंपरा के अनुसार धुनिया, ने अपना अधिकांश जीवन राजस्थान में बिताया -- सांभर, आमेर और अंत में जयपुर के पास नराणा में, जो आज भी दादू पंथ का केंद्र है; कबीर की तरह, जिनका वे आदर करते थे, उन्होंने मूर्ति-पूजा, जाति-भेद और कर्मकांड को अस्वीकार किया, और लोकभाषा में निराकार ईश्वर की भक्ति सिखाई। उनके शिष्यों रज्जब और सुंदरदास ने शिक्षा को आगे बढ़ाया और उनके पद संकलित किए; बाद में संप्रदाय ने सशस्त्र ''नागा'' साधुओं का एक दल भी रखा जो राजपूत शासकों की सेवा करता था। बंगाल का महान भक्ति आंदोलन चैतन्य का वैष्णववाद था, महाराष्ट्र का वारकरी परंपरा, और पंजाब का गुरु नानक की शिक्षा।', concept_group_id = 'l3-t3-his-dadu-panth-rajasthan', source_citation = 'NCERT Class XII, Themes in Indian History II, ''Bhakti-Sufi Traditions''; NCERT Class VII, Our Pasts II.', question_data = '{"craft": "recall"}'::jsonb, options = '[{"id": "a", "body": "Bengal", "body_hi": "बंगाल", "isCorrect": false}, {"id": "b", "body": "Maharashtra", "body_hi": "महाराष्ट्र", "isCorrect": false}, {"id": "c", "body": "Punjab", "body_hi": "पंजाब", "isCorrect": false}, {"id": "d", "body": "Rajasthan", "body_hi": "राजस्थान", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l3-t3-his-kunjali-marakkars' returning concept_group_id;
commit;
